makeMtLab(document.getElementById("lab-l72"),{id:"l72",scenarios:[{"label": "Ví dụ: Mã 12 trên máy dán nắp", "note": "Có trong bảng.", "steps": [{"t": "Sự kiện DOWN, fault_code 12", "html": "<p class=\"mt-calc\">machine_type = CAPPER<\/p>"}, {"t": "Ánh xạ", "html": "<p class=\"mt-calc\">→ EQ-CAP-JAM (Kẹt nắp)<\/p>", "ask": {"q": "Công nhân có phải chọn không?", "o": ["Có", "Không, nhưng có thể sửa"], "a": 1}}]}, {"label": "Ví dụ: Mã mới 33", "note": "Chưa có trong bảng.", "steps": [{"t": "Gán", "html": "<p class=\"mt-calc\">UNMAPPED<\/p>"}, {"t": "Kỹ sư", "html": "<p class=\"mt-calc\">Thêm ('CAPPER', 33, …) vào fault_map<\/p>"}]}, {"label": "Ví dụ: Cùng mã, khác máy", "note": "Mã 12.", "steps": [{"t": "CAPPER 12", "html": "<p class=\"mt-calc\">Kẹt nắp<\/p>"}, {"t": "SCALE 12", "html": "<p class=\"mt-calc\">Cân quá tải<\/p>"}]}, {"label": "Lỗi: Khóa chỉ theo mã", "note": "fault_code là khóa chính.", "steps": [{"t": "Máy cân báo 12", "html": "<p class=\"mt-calc\">Ghi \"Kẹt nắp\"<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Khóa (machine_type, fault_code)<\/p>"}]}, {"label": "Bẫy: Ghi đè lý do người chọn", "note": "Chạy lại UPDATE.", "steps": [{"t": "Công nhân đã sửa lý do", "html": "<p class=\"mt-calc\">UPDATE không có điều kiện IS NULL ghi đè<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Chỉ gán khi reason_id IS NULL<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l72"),"l72",[{"kind": "num", "t": "Ánh xạ", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Trong ca có 18 sự kiện DOWN, 15 có mã đã ánh xạ. Bao nhiêu % tự động?", "a": 83.33, "unit": "%", "tol": 0.01}, {"q": "3 loại máy, mỗi loại 20 mã lỗi. Bảng fault_map đủ có bao nhiêu dòng?", "a": 60}, {"q": "Mã 0 nghĩa là không có mã. 4 sự kiện DOWN mã 0. Công nhân phải chọn mấy lý do?", "a": 4}], "hints": ["15/18.", "Loại × mã."], "why": "83,33 %; 60; 4."}, {"kind": "pick", "t": "Lý do lấy từ đâu?", "d": "<p>Chọn nguồn lý do.<\/p>", "cats": ["Tự động từ mã", "Công nhân chọn"], "items": [{"q": "DOWN, mã 12 đã ánh xạ", "a": 0}, {"q": "IDLE chờ liệu", "a": 1}, {"q": "DOWN, mã 0", "a": 1}, {"q": "DOWN, mã 21 đã ánh xạ", "a": 0}, {"q": "DOWN, mã UNMAPPED", "a": 1}], "hints": ["Có ánh xạ thì tự động.", "Không có mã thì người chọn."], "why": "Mã đã ánh xạ: tự động; IDLE, mã 0, UNMAPPED: người chọn."}, {"kind": "order", "t": "Đóng một sự kiện DOWN", "d": "<p>Sắp xếp.<\/p>", "items": ["Collector đóng sự kiện, ghi fault_code", "Tìm loại máy", "Tra fault_map", "Gán lý do hoặc UNMAPPED", "Hiện cho công nhân xác nhận hoặc sửa"], "hints": ["Tra bảng theo loại máy.", "Người xác nhận ở cuối."], "why": "Đóng → loại máy → tra → gán → xác nhận."}]);
mesSim(document.getElementById("sim-l72"),Object.assign({id:"l72"},{kind:"db",title:"Gán lý do tự động từ mã lỗi",sub:"Bảng mã là ví dụ. Chạy UPDATE gán lý do cho các sự kiện DOWN chưa có lý do.",show:"state_event",rows:9,
 tables:[{name:"machine",cols:[{n:"machine_id",ty:"text",pk:1},{n:"machine_type",ty:"text"}],rows:[{machine_id:"L1-M2",machine_type:"CAPPER"},{machine_id:"L1-M3",machine_type:"SCALE"}]},
  {name:"fault_map",cols:[{n:"machine_type",ty:"text",pk:1},{n:"fault_code",ty:"int",pk:1},{n:"reason_id",ty:"text",nn:1}],rows:[{machine_type:"CAPPER",fault_code:12,reason_id:"EQ-CAP-JAM"},{machine_type:"CAPPER",fault_code:21,reason_id:"MT-SHORT"}]},
  {name:"state_event",cols:[{n:"event_id",ty:"int",pk:1},{n:"machine_id",ty:"text"},{n:"state",ty:"text"},{n:"fault_code",ty:"int"},{n:"reason_id",ty:"text"}],
   rows:[{event_id:1,machine_id:"L1-M2",state:"DOWN",fault_code:12,reason_id:null},{event_id:2,machine_id:"L1-M2",state:"DOWN",fault_code:21,reason_id:null},{event_id:3,machine_id:"L1-M3",state:"DOWN",fault_code:12,reason_id:null},
    {event_id:4,machine_id:"L1-M2",state:"DOWN",fault_code:12,reason_id:"MT-SHORT"},{event_id:5,machine_id:"L1-M2",state:"IDLE",fault_code:0,reason_id:null}]}],
 sql:"UPDATE state_event e\nSET reason_id = coalesce(\n  (SELECT f.reason_id FROM fault_map f JOIN machine m ON m.machine_type = f.machine_type\n   WHERE m.machine_id = e.machine_id AND f.fault_code = e.fault_code),\n  'UNMAPPED')\nWHERE e.state = 'DOWN' AND e.reason_id IS NULL;",
 samples:[{l:"Xem kết quả",sql:"SELECT event_id, machine_id, fault_code, reason_id FROM state_event ORDER BY event_id;"},{l:"Thêm mã cho máy cân",sql:"INSERT INTO fault_map VALUES ('SCALE', 12, 'EQ-SCALE-DRIFT');"},
  {l:"Đặt lại sự kiện 3",sql:"UPDATE state_event SET reason_id = NULL WHERE event_id = 3;"}],
 tasks:[{t:"Chạy UPDATE có sẵn rồi xem kết quả. Sự kiện 3 (máy cân, mã 12) nhận gì?",ok:"UNMAPPED: mã 12 của máy cân khác nghĩa mã 12 của máy dán nắp, nên khóa gồm cả loại máy.",check:s=>s.rows("state_event").some(r=>r.event_id===3&&r.reason_id==="UNMAPPED")},
  {t:"Sự kiện 4 có lý do do người chọn từ trước: UPDATE có ghi đè không? Sự kiện 5 (IDLE) thì sao?",ok:"Không: chỉ gán khi reason_id còn trống. IDLE không có mã lỗi nên để công nhân chọn.",check:(s,c)=>c.has("sql",e=>e.ok&&/select/i.test(e.sql)&&e.rows.length===5)},
  {t:"Kỹ sư bổ sung mã cho máy cân, đặt lại sự kiện 3 và chạy lại UPDATE.",check:s=>s.rows("state_event").some(r=>r.event_id===3&&r.reason_id&&r.reason_id!=="UNMAPPED")}]}));

makeQuiz("quiz72","score72",[{"q": "Vì sao khóa gồm loại máy?", "o": ["Nhanh hơn", "Cùng mã có nghĩa khác nhau trên máy khác nhau", "Bắt buộc SQL", "Tiết kiệm"], "a": 1, "e": "Mã do chương trình PLC đặt."}, {"q": "Mã chưa có trong bảng được xử lý?", "o": ["Gán UNMAPPED và báo kỹ sư", "Bỏ sự kiện", "Gán Khác", "Dừng collector"], "a": 0, "e": "Bổ sung bảng."}, {"q": "Vì sao chỉ gán khi reason_id IS NULL?", "o": ["Nhanh", "Bắt buộc", "Không ghi đè lý do người đã sửa", "Để đếm"], "a": 2, "e": "Tôn trọng xác nhận."}, {"q": "IDLE lấy lý do từ đâu?", "o": ["D101", "fault_map", "ERP", "Công nhân chọn"], "a": 3, "e": "Không có mã lỗi."}]);

